  Item_125189_Name = {
    Text = "Armut Şurubu Şekeri"
  },
  Item_125190_Desc = {
    Text = "Bu Müfreze kaydedildikten sonra, Müfreze becerisi \"Köşkün Yankıları\"nı seçebilirsin.\nIssız köşk, çok fazla sır saklıyor—gücün, takıntının, arzunun sırlarını.\nVe ölümlü dünyaya sevgi dolu, hem \"neşeli\" hem de \"çarpık\" bir bakış fırlatan o uğursuz ilahın gölgesini."
  },
  Item_125190_Name = {
    Text = "Malikâne Yankıları"
  },
  Item_125190_StoryDesc = {
    Text = "Ücra malikâne, fazlasıyla çok Sır barındırıyor—Güç, Takıntı ve Arzuya dair.\nVe \"sevinçli\" ve \"çarpık\" her iki türden aşkla dolup taşan, kötü tanrının ölümlü dünyaya attığı o bakışa dair."
  },
