  Item_130551_Desc = {
    Text = "\"Ders Kaydı\"nda \"Premium Konular\" satın alındıktan sonra kullanılabilir.\n\"Replikler önemli değil, önemli olan tavır!\""
  },
  Item_130551_Name = {
    Text = "Mythag Perde Arası: Nautila"
  },
  Item_130551_StoryDesc = {
    Text = "Ders Kaydı #31"
  },
  Item_130552_Desc = {
    Text = "\"Müfredat\" bölümündeki \"Premium Konular\" satın alındıktan sonra kullanılabilir.\n\"Bir bahse var mısın? Bu oyunun nasıl biteceğine bahse girelim.\""
  },
  Item_130552_Name = {
    Text = "Mythag Perde Arası: Ryker"
  },
  Item_130552_StoryDesc = {
    Text = "Dönem Projesi Sayı #34"
  },
  Item_130553_Desc = {
    Text = "\"Ders Kaydı\"nda \"Premium Konular\" satın alındıktan sonra kullanılabilir.\n\"Özür dilerim... Bu... gösterişli görünüme pek alışık değilim...\""
  },
  Item_130553_Name = {
    Text = "Mythag Perde Arası: Ramona"
