  Item_145606_EmojiName = {Text = "Sürüş"},
  Item_145606_Name = {
    Text = "Nautila-Sürüş"
  },
  Item_145606_StoryDesc = {
    Text = "Müfredat #36"
  },
  Item_145970_Desc = {
    Text = "Bu Müfreze'yi kaydettikten sonra, kadro oluştururken Müfreze becerisi:\"Yalan Olmayan Şey\"i seçebilirsiniz.\n\nOnunla, günahla dolu yılan Aden'deki saf ve bilgisiz olanı ayarttı; onunla, kıskançlıkla kemirilen kraliçe bembeyaz, masum prensesi kandırdı; onunla, yalnızca zekâsıyla silahlanmış bir ölümlü vahşi avcı kadından kaçmayı başardı.\nYine de bu şey bir yalan değildir.\nO yalnızca her insan kalbinin derinliklerinde yuvalanmış, küçük ve dile getirilemeyen arzudur."
  },
  Item_145970_Name = {
    Text = "Yalan Olmayan Şey"
  },
  Item_145970_StoryDesc = {
    Text = "Onunla, günahla yoğrulmuş yılan Cennet'teki saf ve bilgisizi ayarttı; onunla, kıskançlıkla kemirilen kraliçe bembeyaz, masum prensesi kandırdı; onunla, yalnızca zekasıyla silahlanmış bir ölümlü vahşin avcısından kaçıp kurtuldu.\nYine de bu şey bir yalan değildir.\nO yalnızca her insan kalbinin dibinde yuvalanmış, küçük, dile getirilemeyen arzudur."
  },
  Item_146353_Desc = {
    Text = "Yeni ay altındaki karlı zirvelerde süzülen duygusal parçacıklar—temas edildiğinde, belirli küçük bir yalancının kıkırdaması duyulabilir.\nAna Hikaye \"Dağ Ziyafet Kurarken\" içindeki Rezonans Düğümlerini açar.\n\"Dağ Ziyafet Kurarken\" bölümlerinde ilk tamamlama ödülü olarak elde edilir."
  },
  Item_146353_Name = {
    Text = "Bereketler Kalbi"
  },
  Item_146538_Desc = {
    Text = "Açıldıktan sonra, \"Kuzey'in Sonu Yolculuğu\" tüm görevleri tamamlandığında aşağıdaki ek ödüller kazanılabilir"
  },
  Item_146538_Name = {
    Text = "Hyperborea Arşivleri"
  },
  Item_146539_Desc = {
    Text = "Lojistik Departmanı, “Soruşturma”yı tamamlayan Koruyucu’lara özel izinler vermiştir. Her soruşturmanın ardından Koruyucu’lar, bir sonraki seferleri için özel işlenmiş, kıymetli Gümüş satın alabilir.\nStoklar sınırlıdır. Gümüş Anahtar Bize Yol Göstersin."
  },
  Item_146539_Name = {
    Text = "Kilometre Taşı Özel·Yıldız Hükümranlığı VI"
  },
