  Item_50032_Name = {
    Text = "Çene Kemiği"
  },
  Item_51105_Desc = {
    Text = "\"Hikâyelerin Büyüsü·Tekrar\" Etkinliği’nde, bu eşya \"Kurgulanmış Gizem\" i tamamlayarak veya Etkinlik Başarımlarını bitirerek elde edilir. \"Gizemli Kodeks Emporumu\" nda Borsa için kullanılabilir.\nİlham, gecenin göğünü yaran bir meteor gibi gelip geçicidir. Fark şu ki, senin onu sonsuza dek muhafaza etmenin bir yolun var."
  },
  Item_51105_Name = {
    Text = "Savrulan İlham"
  },
  Item_51265_Desc = {
    Text = "\"Hikayenin Büyüsü·Tekrar\" etkinliğinde \"Senaryo Muamması\"nı geçerek veya etkinlik başarımlarını tamamlayarak elde edilir; \"Büyülü Senaryo Mağazası\"nda takas yapmak için kullanılan eşya.\nİlham geçicidir, gece gökyüzünde süzülen bir kayan yıldız gibi. Farkı şu ki, onu sonsuza dek tutmanın bir yolu var.\n\nEn az {s1} adet düşer"
