  Item_51996_StoryDesc = {
    Text = "Ders Kaydı #6"
  },
  Item_52037_Desc = {
    Text = "\"Ruhlar Sunak\"ında borsa için eşya.\nÖzünü sun, ey Adak Sunucu. Tüm dilekler İlahi Diyar tarafından yerine getirilecektir."
  },
  Item_52037_Name = {
    Text = "Adak Sunucunun İliği"
  },
  Item_52038_Desc = {
    Text = "\"Kan Sunak\"ında borsa için eşya.\nKanını sun, ey Adak Sunucu. Tüm günahlar İlahi Diyar tarafından cezalandırılacaktır."
  },
  Item_52038_Name = {
    Text = "Adak Sunucunun Kanı"
  },
  Item_52039_Desc = {
    Text = "\"Gözyaşları Sunak\"ında borsa için eşya.\nGözyaşlarını sun, ey Adak Sunucu. Tüm acılar İlahi Diyar tarafından geri ödenecektir."
  },
  Item_52039_Name = {
    Text = "Adak Sunucunun Gözyaşları"
  },
  Item_52069_Desc = {
    Text = "Lemurya'da süzülen duygusal parçacıklar. \"İlahi Yeniden Doğuş\" Etkinlik Oyunundaki Rezonans Düğümlerini açar.\n\"Uçurum Kurbanı\"ndaki Başarı Ödülleri tamamlanarak elde edilebilir."
  },
  Item_52069_Name = {
    Text = "Bağlılık Kalbi"
  },
  Item_52070_Desc = {
    Text = "\"Uçurum Kurbanı\" etkinliğinde başarı ödülü.\n\"Onun iradesi hâlâ derinliklerde hafif uykuda... Geri kalmamalıyız.\""
  },
  Item_52070_Name = {
    Text = "Gümüş Anahtar Adına: Miryam"
  },
  Item_52070_StoryDesc = {
    Text = "Miryam Oynanış Etkinliği"
  },
