    Text = "\"Gözyaşları Sunağı\"nda takas için eşya.\nGözyaşlarını sun, ey Kurban. Tüm acılar Tanrı'nın Diyarı tarafından karşılık bulacak.\n\nEn az {s1} düşürür"
  },
  Item_52173_Name = {
    Text = "Adak Sunucunun Gözyaşları"
  },
  Item_52174_Desc = {
    Text = "\"Kan Sunağı\"nda takas için eşya.\nKanını sun, ey Kurban. Tüm günahlar Tanrı'nın Diyarı tarafından cezalandırılacak.\n\nEn az {s1} düşürür"
  },
  Item_52174_Name = {
    Text = "Adak Sunucunun Kanı"
  },
