    Text = "\"Kan Sunağı\"nda takas için eşya.\nKanını sun, ey Kurban. Tüm günahlar Tanrı'nın Diyarı tarafından cezalandırılacak.\n\nEn az {s1} düşürür"
  },
  Item_52175_Name = {
    Text = "Adak Sunucunun Kanı"
  },
  Item_52176_Desc = {
    Text = "\"Ruhlar Sunağı\"nda takas için eşya.\nÖzünü sun, ey Kurban. Tüm arzular Tanrı'nın Diyarı tarafından karşılanacak.\n\nEn az {s1} düşürür"
  },
  Item_52176_Name = {
    Text = "Adak Sunucunun İliği"
  },
  Item_52177_Desc = {
