  Item_52177_Name = {
    Text = "Adak Sunucunun İliği"
  },
  Item_52178_Desc = {
    Text = "\"Gözyaşları Sunağı\"nda takas için eşya.\nGözyaşlarını sun, ey Kurban. Tüm acılar Tanrı'nın Diyarı tarafından karşılık bulacak.\n\nEn az {s1} düşürür"
