  Item_54124_Name = {
    Text = "Rogers-Paniklemiş"
  },
  Item_54124_StoryDesc = {
    Text = "Ders Kaydı #11"
  },
  Item_54125_Desc = {
    Text = "\"Ah, hepsi şans, saf şans.\""
  },
