    Text = "Konuşamıyor"
  },
  Item_54126_Name = {
    Text = "Koum-Konuşamaz"
  },
  Item_54126_StoryDesc = {
    Text = "Traphase - Sezon 10"
  },
  Item_54127_Desc = {Text = "\"Ne?!\""},
  Item_54127_EmojiName = {
    Text = "Şoka Girmiş"
  },
  Item_54127_Name = {
    Text = "Sarah-Şokta"
  },
  Item_54127_StoryDesc = {
    Text = "Traphase - Sezon 10"
  },
  Item_54128_Desc = {
    Text = "\"Aptallara karşı epey hoşgörülüyümdür.\""
