  Item_65615_Desc = {
    Text = "Derin Deniz’in yükselen dalgaları, bilincin sınırlarına çarpar.\nYabancı düşlerin Aşınması’na karşı kullanılan ritüel, \"Uçurum Kurbanı\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_65615_Name = {
    Text = "Gelgit Aşınma Savunma Ayini"
  },
  Item_65616_Desc = {
    Text = "En Karanlık Derinlikler’de hafif uykuda yatan Egemenlik’in doğuşu, tüm Zihin Denizi’ni çarpıtacaktır.\nYabancı düşlerin Aşınması’na direnmek için tasarlanan ritüel, \"Uçurum Kurbanı\" sınırlı süreli etkinliği boyunca Alınabilir olacaktır."
  },
  Item_65616_Name = {
    Text = "Tanrı Diyarı Kraliyet Doğum Ayini"
  },
  Item_65618_Desc = {
    Text = "Düş Diyarı’ndaki Felaket, Muhafız’ın Luminis’ini de ruhsal Rezonans yoluyla bozar.\nDüş Diyarı Aşınması’na karşı kullanılan ritüeller, \"Uçurum Kurbanı\" sırasında sınırlı süreli bir teklif olarak Alınabilir."
  },
  Item_65618_Name = {
    Text = "Felaket Uyarı Ayini"
  },
  Item_65752_Desc = {
    Text = "\"Ego Diseksiyonu\"nda takas için eşya.\n\nTüm anılar sadık ve güvenilir değildir.\nSana bir sır söyleyeyim: β tam bir yalancıdır; yalan söylüyor.\n\nEn az {s1} düşürür"
  },
  Item_65752_Name = {
    Text = "Hafıza Bulmacası α"
  },
  Item_65753_Desc = {
    Text = "\"Ego Diseksiyonu\"nda takas için eşya.\n\nAh, kıskançlık! Sen söylentilerin anasısın.\nα'yı suçladığım için derinden pişmanım. Bildiğim kadarıyla, yalan söyleyen o.\n\nEn az {s1} düşürür"
  },
  Item_65753_Name = {
    Text = "Hafıza Bulmacası β"
  },
  Item_65754_Desc = {
    Text = "\"Ego Diseksiyonu\"nda takas için eşya.\n\nGerçek: Hem α hem de β yalan söylüyor.\nŞimdi, tamamen yok olmayı göze alarak bunu sana söylüyorum @#¥%......&\n\nEn az {s1} düşürür"
  },
