  Item_68846_Desc = {
    Text = "“O ses de ne? Burada mı? Geri mi döndü...”"
  },
  Item_68846_EmojiName = {
    Text = "Uyanıklık"
  },
  Item_68846_Name = {
    Text = "Winkle-Uyanıklık"
  },
  Item_68846_StoryDesc = {
    Text = "Traphase - Sezon 12"
  },
  Item_68847_Desc = {
    Text = "\"Şimdi hatırladım! Böyle düzeltilmeli!\""
  },
  Item_68847_EmojiName = {Text = "Anladım!"},
  Item_68847_Name = {
    Text = "Nautila-Anlaşıldı!"
  },
  Item_68847_StoryDesc = {
    Text = "Traphase - Sezon 13"
  },
  Item_68848_Desc = {
    Text = "\"Şansını denemek ister misin? Ben ya hep ya hiç oynarım, çekinme.\""
  },
  Item_68848_EmojiName = {
    Text = "Bir Şansını Dene"
  },
  Item_68848_Name = {
    Text = "Ryker-Bir Şans Ver"
  },
  Item_68848_StoryDesc = {
    Text = "Ders Kaydı #13"
  },
  Item_68849_Desc = {
    Text = "“Gerçekten imkânsız mı... arkadaşlarımı denizden geri getirmek?”"
  },
  Item_68849_EmojiName = {Text = "Zavallı"},
  Item_68849_Name = {
    Text = "Aurita-Acıklı"
  },
  Item_68849_StoryDesc = {
    Text = "Ders Kaydı #12"
  },
  Item_68850_Desc = {
    Text = "\"Sistem arızası...\""
  },
  Item_68850_EmojiName = {Text = "Bunaklık"},
  Item_68850_Name = {
    Text = "Erica-Bunaklık"
  },
  Item_68850_StoryDesc = {
    Text = "Traphase - Sezon 13"
  },
  Item_68851_Desc = {
    Text = "\"Tam bir delilik!\""
  },
  Item_68851_EmojiName = {Text = "Kükreme"},
  Item_68851_Name = {
    Text = "Golyat-Kükreme"
  },
  Item_68851_StoryDesc = {
    Text = "Ders Kaydı #12"
  },
  Item_68852_Desc = {
    Text = "\"Köşk mü? Ne köşkü? Benim köşküm yok ki!\""
  },
  Item_68852_EmojiName = {Text = "Terbiyesiz"},
  Item_68852_Name = {
    Text = "Jenkin-Terbiye Yok"
  },
  Item_68852_StoryDesc = {
    Text = "Ders Kaydı #13"
  },
  Item_68853_Desc = {
    Text = "\"İnsanlar gerçekten karmaşık varlıklar...\""
  },
  Item_68853_EmojiName = {
    Text = "Ruhu Sönmüş"
  },
  Item_68853_Name = {
    Text = "Nergis-Moralsiz"
  },
  Item_68853_StoryDesc = {
    Text = "Traphase - Sezon 12"
  },
  Item_68854_Desc = {
    Text = "\"Kimsenin sevmediği bir balığım ben...\""
  },
  Item_68854_EmojiName = {
    Text = "Duvar Köşesi"
  },
  Item_68854_Name = {
    Text = "Caecus-Duvar Köşesi"
  },
  Item_68854_StoryDesc = {
    Text = "Traphase - Sezon 13"
  },
  Item_68855_Desc = {
    Text = "“Demek mesele böyle. Söylediklerin mantıklı, bunu ciddiyetle düşüneceğim.”"
  },
  Item_68855_EmojiName = {
    Text = "Gerçekten Öyle"
  },
  Item_68855_Name = {
    Text = "Horla-Elbette"
  },
  Item_68855_StoryDesc = {
    Text = "Ders Kaydı #13"
  },
  Item_68856_Desc = {
    Text = "\"Vay canına, Usta, harikasınız!\""
  },
  Item_68856_EmojiName = {Text = "Tapınma"},
  Item_68856_Name = {
    Text = "Lily’ye Tapınma"
  },
  Item_68856_StoryDesc = {
    Text = "Traphase - Sezon 13"
  },
  Item_68857_Desc = {
    Text = "\"Hoşça kal, anne! Bu gece yelken açıyorum!\""
  },
  Item_68857_EmojiName = {Text = "Aylaklık"},
  Item_68857_Name = {
    Text = "Murphy-Aylaklık"
  },
  Item_68857_StoryDesc = {
    Text = "Ders Kaydı #13"
  },
  Item_68858_Desc = {
    Text = "“Efendim, birlikte ata binmeye var mısınız?”"
  },
  Item_68858_EmojiName = {Text = "Mutlu"},
  Item_68858_Name = {
    Text = "Ogier-Mutlu"
  },
  Item_68858_StoryDesc = {
    Text = "Traphase - Sezon 12"
  },
  Item_68859_Desc = {
    Text = "\"Ziyaretiniz için teşekkür ederim.\""
  },
  Item_68859_EmojiName = {
    Text = "Perde Kapanışı"
  },
  Item_68859_Name = {Text = "Sorel-Veda"},
  Item_68859_StoryDesc = {
    Text = "Ders Kaydı #12"
  },
  Item_69844_Desc = {
    Text = "Yüksek rütbeli birinin cenazesinde icra edilen bir ağıt; ölü Ruhları teselli eder ve onların ebedi Dinlenme’si için dua eder.\n\"Güle Mektup\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69844_Name = {
    Text = "Kutsanmış Ruh Ayini"
  },
  Item_69845_Desc = {
    Text = "Yüksek rütbeli birinin cenazesinde icra edilen bir ağıt; onun görkemi ve hatırası sonsuza dek Tahammül edecektir.\n\"Güle Mektup\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69845_Name = {
    Text = "Övgü Ayini"
  },
  Item_69846_Desc = {
    Text = "Yüksek rütbeli birinin cenazesinde icra edilen bir ağıt; yaşayanların ölüye duyduğu yas ve Anımsama’yı dile getirirken, ölümün bir Son değil, ebedi hayata giden Yolun başlangıcı olduğuna sıkı sıkıya inanır.\n\"Güle Mektup\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69846_Name = {
    Text = "Ölüler İçin Kutsal Ayin"
  },
  Item_69851_Desc = {
    Text = "Elworth'un zirvesinde yeni filizlenmiş bir karahindiba tohumu—donmuş topraktan fışkıran, canlılıkla taşan küçücük bir filiz.\n\"Karlar Eridiğinde·Tekrar\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69851_Name = {
    Text = "Felaket Uyarı Ayini"
  },
  Item_69852_Desc = {
    Text = "Elworth'un zirvesinde yeni filizlenmiş bir herdemyeşil tohumu. Bu inatçı fidan, rüzgârı, ayazı, yağmuru ve karı sonunda alt ederek ulu bir dev ağaca dönüşecek.\n\"Karlar Eridiğinde·Tekrar\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69852_Name = {
    Text = "Tanrı Diyarı Kraliyet Doğum Ayini"
  },
  Item_69853_Desc = {
    Text = "Elworth'un zirvesinde yeni filizlenmiş beyaz bir çiçek tohumu; dalı ve yaprakları buzdan ve kardan—acı soğuk bile kokusunu solduramaz.\n\"Karlar Eridiğinde·Tekrar\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69853_Name = {
    Text = "Gelgit Aşınma Savunma Ayini"
  },
  Item_69854_Desc = {
    Text = "Yalnızca dizeler okunduğunda açılan esrarengiz bir kutu.\nOna çiçeklerin rüyasını tasvir et; sana bir gül buketi bahşedecek.\n“Bahar Solmadan Önce” sırasında sınırlı sayıda."
  },
  Item_69854_Name = {
    Text = "Taç Yaprağı Dizeleri"
  },
  Item_69855_Desc = {
    Text = "Yalnızca dizeler okunduğunda açılan esrarengiz bir kutu.\nHayal tasvirin tam isabet olduğunda, sana Gerçek’i görme izni verecek.\n“Bahar Solmadan Önce” sırasında sınırlı sayıda."
  },
  Item_69855_Name = {
    Text = "Esin Dizeleri"
  },
  Item_69856_Desc = {
    Text = "Yalnızca dizeler okunduğunda açılan esrarengiz bir kutu.\nOna geçmişini anlat; sana bir parça Hafıza dokunuşu bahşedecek.\n“Bahar Solmadan Önce” sırasında sınırlı sayıda."
  },
  Item_69856_Name = {
    Text = "Aşk Dizeleri"
  },
  Item_69860_Desc = {
    Text = "Hiçbir bebeğe bağlı olmadığı hâlde kendi kendine dönen bir dişli takımı; yaklaştıkça, hafif bir Fısıltı gibi tıslayan bir sürtünme sesi yayar."
  },
  Item_69860_Name = {
    Text = "Çift Sarmal Kukla Parçaları"
  },
  Item_69861_Desc = {
    Text = "Dert-Giderme Dükkânı'nda satılan bir hediye kutusu; herhangi bir büyük mağazadaki en yeni mallardan bile daha zarif—gerçek bir kafayla takas edilir.\n\"Yağmur Kasabasının Hayaleti\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69861_Name = {
    Text = "Cadı Mağazası Hediye Kutusu"
  },
  Item_69862_Desc = {
    Text = "Dert-Giderme Dükkânı'nda satılan bir hediye kutusu; dünyanın dört bir yanından nadir ve egzotik Gizli Hazineler içerir—taze, sağlam bir kafatasıyla takas edilir.\n\"Yağmur Kasabasının Hayaleti\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69862_Name = {
    Text = "Harika Cadı Hediye Kutusu"
  },
  Item_69863_Desc = {
    Text = "Kaygı Giderme Dükkanı'nda satılan bir hediye kutusu; dükkân sahibinin özel koleksiyonundan seçilmiş, daha önce hiç duymadığın türden harikalarla dolu gizli bir hazine—koleksiyonluk güzellikte bir kafatasıyla takas edilmek üzere.\n\"Yağmur Kasabasının Hayaleti\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69863_Name = {
    Text = "Gizli Cadı Hediye Kutusu"
  },
  Item_69867_Desc = {
    Text = "Belirli bir hanımefendiden gelen bir beş çayı daveti. Gel, leziz tatlıların tadına bak ve oyuncak bebekler ve ayıcıklarla dans et.\n\"Yıldızlar Yerinde\" sırasında sınırlı bir süre için alınabilir."
  },
  Item_69867_Name = {
    Text = "Hanımefendi Davetiye Paketi"
  },
  Item_69868_Desc = {
    Text = "Belirli bir hanımefendininkine benzeyen bir elbise—onu giymek, hanımefendinin zarafetini ve asaletini taşıyana bahşeder.\n\"Yıldızlar Yerinde\" sırasında sınırlı bir süre için alınabilir."
  },
  Item_69868_Name = {
    Text = "Hanımefendi Elbise Paketi"
  },
  Item_69869_Desc = {
    Text = "Belirli bir hanımefendininkine benzeyen bir Güneş Şemsiyesi—onu açmak, başını asla eğmeyen birinin özgüvenini sana bahşeder.\n\"Yıldızlar Yerinde\" sırasında sınırlı bir süre için alınabilir."
  },
  Item_69869_Name = {
    Text = "Hanımefendi Şemsiye Paketi"
  },
  Item_69870_Desc = {
    Text = "Ünlü ticari denizcilik rotalarını gösteren bir deniz haritası; tüccarları güvenle limana ulaştırır.\n\"Fırtınanın Altında Salınış\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69870_Name = {
    Text = "Altın Yolun Kılavuzluğu"
  },
  Item_69871_Desc = {
    Text = "Clementine'in Akıl Kliniği'nden özel bir reçete; uzun süreli, yinelenen ruhsal bozuklukları Bastırma gücüne sahiptir.\n\"Hafızanın Altına Gömülü\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69871_Name = {
    Text = "Kararsız Delilik Reçetesi"
  },
  Item_69872_Desc = {
    Text = "Clementine'in Akıl Kliniği'nden özel bir reçete; Delilik uçurumuna kalıcı olarak düşmüş olanları bile kurtarabilecek güçtedir.\n\"Hafızanın Altına Gömülü\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69872_Name = {
    Text = "Kalıcı Delilik Reçetesi"
  },
  Item_69873_Desc = {
    Text = "Clementine'in Akıl Kliniği'nden özel bir reçete; Geçici psikolojik Travma'yı tedavi edebilir.\n\"Hafızanın Altına Gömülü\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69873_Name = {
    Text = "Geçici Delilik Reçetesi"
  },
  Item_69874_Desc = {
    Text = "Derin Deniz’in yükselen dalgaları, bilincin sınırlarına çarpar.\nYabancı düşlerin Aşınması’na karşı kullanılan ritüel, \"Uçurum Kurbanı\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69874_Name = {
    Text = "Gelgit Aşınma Savunma Ayini"
  },
  Item_69875_Desc = {
    Text = "En Karanlık Derinlikler’de hafif uykuda yatan Egemenlik’in doğuşu, tüm Zihin Denizi’ni çarpıtacaktır.\nYabancı düşlerin Aşınması’na direnmek için tasarlanan ritüel, \"Uçurum Kurbanı\" sınırlı süreli etkinliği boyunca Alınabilir olacaktır."
  },
  Item_69875_Name = {
    Text = "Tanrı Diyarı Kraliyet Doğum Ayini"
  },
  Item_69876_Desc = {
    Text = "Düş Diyarı’ndaki Felaket, Muhafız’ın Luminis’ini de ruhsal Rezonans yoluyla bozar.\nDüş Diyarı Aşınması’na karşı kullanılan ritüeller, \"Uçurum Kurbanı\" sırasında sınırlı süreli bir teklif olarak Alınabilir."
  },
  Item_69876_Name = {
    Text = "Felaket Uyarı Ayini"
  },
  Item_69877_Desc = {
    Text = "Üzerinde gizli bir rota işaretli bir deniz haritası; insanı dinlenebileceği küçük bir adaya götürür.\n\"Fırtınanın Altında Salınış\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69877_Name = {
    Text = "Gök Mavisi Deniz’de Sığınak"
  },
  Item_69885_Desc = {
    Text = "Narin ve girift kukla bileşenleri, teknolojinin ve Delilik’in ışıltısıyla titreşiyor."
  },
  Item_69885_Name = {
    Text = "İşlenmiş Kukla Parçaları"
  },
  Item_69889_Desc = {
    Text = "Üzerine büyülerle mühür vurulmuş, Ziyaret seviyesinde erzak içeren bronz bir kutu. Temel bir Uyanış ayininden çoktan geçirilmiş ve açan kişi için hiçbir tehlike taşımıyor.\nOrası fazlasıyla yoksuldu; en iyi Sunular bile ancak bu seviyeye ulaşabiliyordu.—Kathigu-Ra"
  },
  Item_69889_Name = {
    Text = "Bronzun Sunduğu\"Hediye\""
  },
  Item_69890_Desc = {
    Text = "Uçurumî bir aura yayan, etrafında koyu kırmızı bir sis dönen devasa bir sandık. İçinde muazzam miktarda erzak barındırır, ancak açarken lütfen yardım için mutlaka profesyonellere haber verin.\nBu kadar gerilme, üstteki tehlikeyi çoktan temizledim; yalnızca nereden geldiğini bilesin diye bu görsel efekti bıraktım.—Kathigu-Ra"
  },
  Item_69890_Name = {
    Text = "Kızıl Uçurumun\"Hediyesi\""
  },
  Item_69891_Desc = {
    Text = "Altın ışıkla titreşen bir kap; kenarlarından durmaksızın akan sıvı altın, içinde kıymetli sunuları barındırıyor.\nDürüst olmak gerekirse, bu kutunun içindekilerden daha değerli olduğunu düşünüyorum. Maddi şeyler sana ancak sınırlı ölçüde yardım edebilir, değil mi? — Kathigu-Ra"
  },
  Item_69891_Name = {
    Text = "Altın Akan\"Hediye\""
  },
  Item_69892_Desc = {
    Text = "Asla Yaratıcı Tanrı’yı, “Ögeler”i ve doktorunun reçetesini sorgulama.\nKoruyucu’nun fiziksel ve zihinsel sağlığını güvenceye almak için iyi bir reçete, “Çoklu Şifa” sırasında sınırlı bir süreliğine Alınabilir."
  },
  Item_69892_Name = {
    Text = "Dissosiyasyon İyileşme Tedavisi"
  },
  Item_69893_Desc = {
    Text = "Ya bir kür tedavi etkisiz kalırsa? O hâlde bir kür daha uygulayalım!\n“Kilise Koruyucusu”nun bedensel ve ruhsal sağlığını güvence altına almak için, “Çoklu Şifa” sırasında geçici olarak sağlanan iyi bir çare."
  },
  Item_69893_Name = {
    Text = "Dissosiyasyon Pekiştirme Tedavisi"
  },
  Item_69894_Desc = {
    Text = "Ya yanlışlıkla çoklu kişilik geliştirirsem?\nMerak etme, Mythag çoktan hazırladı!\nKoruyucu’nun zihinsel ve fiziksel sağlığını güvenceye almak için iyi bir reçete, \"Çoklu Şifa\" sırasında geçici olarak alınabilir."
  },
  Item_69894_Name = {
    Text = "Dissosiyasyon Akut Tedavisi"
  },
  Item_69895_Desc = {
    Text = "Kadim deniz rotalarını gösteren bir deniz haritası; üzerinde Efsanevi bir Gizli Hazine'nin yerini işaretlediği söylenir.\n\"Fırtınanın Altında Salınış\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69895_Name = {
    Text = "Uçurumda Gizlenen Hazineler"
  },
  Item_69896_Desc = {
    Text = "Necrovia’daki Kemik Odası Sarayı’nın ziyafet yemeği; Gulyabanilerin Kralı’nın bizzat hazırladığı ana yemek, her yiyenin arzuladığı bir lezzet.\n\"Ölümsüzlerin Estetiği\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69896_Name = {
    Text = "Ruh Bayramı Ana Yemeği"
  },
  Item_69897_Desc = {
    Text = "Necrovia’daki Kemik Odası Sarayı’nın ziyafet yemeklerinde, tüm çorbalar özenle seçilmiş malzemelerden hazırlanır.\n\"Ölümsüzlerin Estetiği\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69897_Name = {
    Text = "Ruh Bayramı Koyu Çorba"
  },
  Item_69898_Desc = {
    Text = "Necrovia’daki Kemik Odası Sarayı’nın ziyafet yemekleri titizlikle hazırlanır; hatta mezeler bile büyük bir özenle yapılır.\n\"Ölümsüzlerin Estetiği\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69898_Name = {
    Text = "Ruh Bayramı Meze"
  },
  Item_69899_Desc = {
    Text = "Hikâye, büyülü bir gümüş filmin kaybolmasıyla başlar—bir kız ile efendisinin gizemli öyküsü.\n\"Hikâyelerin Büyüsü\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69899_Name = {
    Text = "Gerilim Hikâyesi Filmi"
  },
  Item_69900_Desc = {
    Text = "Hikâyede bir Perde Arası; beceriksiz, acemi bir aktör sahneye çıkar—bir kız ile hayalet hırsızın komik öyküsü.\n\"Hikâyelerin Büyüsü\" sırasında sınırlı bir süre için Alınabilir."
  },
  Item_69900_Name = {
    Text = "Komedi Hikâye Filmi"
  },
  Item_69901_Desc = {
    Text = "Hikâye sona yaklaşırken, gün batımına karşı siluetleri düşen yoldaşlar bir anı defterine hapsolur—bir kız çocuk ile bir balinanın fantastik masalı.\n\"Hikâyelerin Büyüsü\" sırasında sınırlı bir süre için alınabilir."
  },
  Item_69901_Name = {
    Text = "Fantastik Hikâye Filmleri"
  },
  Item_69902_Desc = {
    Text = "Bilinmeyen bir biçimde aşınmış, paslı metal yaraları andıran kırık kukla parçalarından siyah irin ve kan sızıyor."
  },
  Item_69902_Name = {
    Text = "Paslanmış Kukla Parçaları"
  },
  Item_69985_Desc = {
    Text = "Kapı, onu ilk Kudret’e yaklaştırmak için açılır—O’ndan korkmayan yoktur, O’nu arzulamayan da yoktur.\nMythag’ın altındaki Kara Havuz’dan gelen, Kapının Ötesinde’nin gücüyle tavlanmış, ilk öz’e gitgide yaklaşan gizemli bir çekirdek; Uyananların akıl almaz yüksekliklere yükselmesine yardım eder."
  },
  Item_69985_Name = {
    Text = "Arıtılmış İlksel Ruh Çekirdeği"
  },
  Item_69986_Desc = {
    Text = "Kara Havuz’a saçılmış parçalar; Sonsuz Kapı’nın ışığında Kaynak’ın gücü doğacağı ânı beklemektedir.\nMythag’ın derinliklerinden gelen, Kapının Ötesinde’nin gücüyle tavlanmış gizemli parçalar. Arıtılmış İlksel Ruh Çekirdeği’ne dönüştürülebilir."
  },
  Item_69986_Name = {
    Text = "Rafine Gnosis Parçası"
  },
  Item_70143_Desc = {
    Text = "\"Şehvetin Filizlenmesi\"nde takas yapmak için kullanılan eşya.\n\nKüçücük, yuvarlak bir tohum.\nEr ya da geç filizlenecek, kök salacak, gökyüzünü örten gür bir ağaca dönüşecek.\n\nEn az {s1} adet düşer"
