  Item_70292_Desc = {
    Text = "\"Yıldızların Ötesinde: Süreli Ön Sipariş\"te Alınabilir.\n\"Yıldızlar doğru konumlarına ulaştığında, ulu @1 dünyaya gelecektir.\""
  },
  Item_70292_Name = {
    Text = "Yıldızlar Doğru Konumda Olduğunda"
  },
  Item_70292_StoryDesc = {
    Text = "V2.0 Sürümü Ön Sipariş Etkinliği"
  },
  Item_70919_Desc = {
    Text = "Bu Müfrezeyi kaydettikten sonra, Müfreze becerisi \"Yıldızların Kutsaması\"nı seçebilirsin.\n\nO Tacı o seçti, o Taç da onu seçti.\nYeni Kral’ın ruhu, bir an için kadim tanrıyla rezonansa girdi. Arkasında ezici bir Gölge belirdi ve ülkeye ebedi huzur getirdi."
  },
  Item_70919_Name = {
    Text = "Yıldızların Kutsaması"
  },
  Item_70919_StoryDesc = {
    Text = "O Tacı o seçti, o Taç da onu seçti.\nYeni kralın ruhu, bir an için kadim tanrıyla rezonansa girdi. Arkasında ezici bir Gölge belirdi ve ülkeye ebedi huzur getirdi."
  },
  Item_71281_Desc = {
    Text = "Ey acı çeken ruhlar, asla umudunuzu yitirmeyin; hayırsever başrahip sizin için Yaratıcı Tanrı'ya Saygı Duruşunda bulunacak.\n\"Soul Shepherd·Tekrar\" süresince sınırlı bir süre için Alınabilir."
  },
  Item_71281_Name = {
    Text = "Ayin Sırasında Dua"
  },
  Item_71282_Desc = {
    Text = "Ey, acı çeken ruhlar, mükâfatınız yakındır; hayırsever başrahip, Ulu Baba adına üzerinize lütuflar yağdıracaktır.\n\"Soul Shepherd: Rerun\" süresince sınırlı bir zaman için Alınabilir."
  },
  Item_71282_Name = {
    Text = "Ayin Sonrası Kutsama"
  },
  Item_71283_Desc = {
    Text = "Ey acı çeken ruhlar, kaybolmuş hissetmenize gerek yok; hayırsever başrahip size rehberlik edecek.\n\"Soul Shepherd·Tekrar\" süresince sınırlı bir süre için Alınabilir."
  },
  Item_71283_Name = {
    Text = "Ayin Öncesi Rehberlik"
  },
