  Item_72089_Desc = {
    Text = "\"Bir palamut, bir maceranın başlangıcını simgeler; daha çok palamuda ihtiyacımız var!\" — Ignatius.\nIgnatius’un sihirli gücünden yoğunlaşmış palamutlar, \"Round Wonder\"da envanter borsasında kullanılır."
  },
  Item_72089_Name = {
    Text = "Sihirli Palamut"
  },
  Item_72089_StoryDesc = {
    Text = "Sıram ile Ortak Etkinlik"
  },
  Item_72095_Desc = {
    Text = "Bu Müfreze kaydedildikten sonra, Traphase Dizilimi sırasında Müfreze Becerisi: “Tavernanın Kapısı”nı seçebilirsin.\n\nBir dünya sona erdiğinde, başka bir dünyanın Prolog’u başlar. Hikâyeler, ince şarapla birlikte insanlar tarafından aktarılacak, ama zaman her şey için yanıtlar yazacaktır."
  },
  Item_72095_Name = {
    Text = "Tavernanın Kapısı"
  },
  Item_72095_StoryDesc = {
    Text = "Bir dünya sona erdiğinde, başka bir dünyanın Prolog’u başlar. Hikâyeler, ince şarapla birlikte insanlar tarafından aktarılacaktır; fakat zaman, her şey için cevaplar yazacaktır."
  },
  Item_72824_Desc = {
    Text = "Umut diyarı kıtasında bulunan küçük bir tavernada, farklı dünyaları birbirine bağlayan bir ışınlanma kapısı vardır.\nTaverna sahibi Ignatiss, geçmiş kahramanların hikâyelerini anlatmak için Cosmos Kart adlı bir kart oyunu yaratmıştır."
  },
  Item_72824_Name = {
    Text = "Sıram: Kozmos Kartı"
  },
  Item_72824_StoryDesc = {
    Text = "Sıram ile Ortak Etkinlik"
  },
  Item_72834_Desc = {
    Text = "\"Biçimsiz Olanın Hediye Kartı\" ile alınabilir.\n\"He ya, yeni demlediğim örümcek otlu çayımı denemek isteyen var mı?\""
  },
  Item_72834_Name = {
    Text = "Gümüş Anahtar Adına: Sylvia"
  },
  Item_72834_StoryDesc = {
    Text = "Görünüm Koleksiyon Kuponu Özel"
  },
  Item_72835_Desc = {
    Text = "\"Bağlı Dokumacı\" etkinliğindeki başarı ödülü.\n\"Aman, lütfen dokumamı bölmeyin—bundan daha önemli bir şey yok...\""
  },
  Item_72835_Name = {
    Text = "Gümüş Anahtar Adına: Arachne"
  },
  Item_72835_StoryDesc = {
    Text = "Arachne Oynanış Etkinliği"
  },
  Item_72836_Desc = {
    Text = "\"Gösterin... gerçekten de... epey bir çaba.\""
  },
  Item_72836_EmojiName = {Text = "Çaresiz"},
  Item_72836_Name = {
    Text = "Hameln-Çaresiz"
  },
  Item_72836_StoryDesc = {
    Text = "Traphase - Sezon 18"
  },
  Item_72837_Desc = {
    Text = "<Available:\"Tuvalin Karanlık Yüzü\" etkinliğinde başarı ödülü.>\n<Memory:\"Yalnızca gözlerinin gördüğünü resmedebiliyorsan, sıradan bir ölümlüden ne farkın kalır?\">"
  },
  Item_72837_Name = {
    Text = "Gümüş Anahtar Adına: Pickman"
  },
  Item_72837_StoryDesc = {
    Text = "Pickman Oynanış Etkinliği"
  },
  Item_72838_Desc = {
    Text = "Koşmayı bırak. Gerçekten çok lezzetli. Gel de tadına bak!\""
  },
  Item_72838_EmojiName = {Text = "Çay Saati"},
  Item_72838_Name = {
    Text = "Selvia-Çay Saati"
  },
  Item_72838_StoryDesc = {
    Text = "Görünüm Koleksiyon Kuponu Özel"
  },
  Item_72839_Desc = {
    Text = "“İyi geceler. Aigis yarın da yine uslu bir çocuk olacak.”"
  },
  Item_72839_EmojiName = {
    Text = "İyi Geceler"
  },
  Item_72839_Name = {
    Text = "Aigis-İyi Geceler"
  },
  Item_72839_StoryDesc = {
    Text = "Ders Kaydı #23"
  },
  Item_72840_Desc = {
    Text = "\"Teşekkürler, Efendim!\""
  },
  Item_72840_EmojiName = {
    Text = "Teşekkür Ederim"
  },
  Item_72840_Name = {
    Text = "Lily-Teşekkür Ederim"
  },
  Item_72840_StoryDesc = {
    Text = "Ders Kaydı #22"
  },
  Item_72841_Desc = {
    Text = "\"Ders Kaydı\"nda \"Premium Konular\" ile açılır: \n\"Çiçeklerimi alır mısınız?\""
  },
  Item_72841_Name = {
    Text = "Gümüş Anahtar Adına: Colette"
  },
  Item_72841_StoryDesc = {
    Text = "Ders Kaydı #19"
  },
  Item_72842_Desc = {
    Text = "“Ne, ne, ne? Bütün bunlar da ne? Benden kafa yoran işleri isteme.”"
  },
  Item_72842_EmojiName = {Text = "Bilgelik"},
  Item_72842_Name = {
    Text = "Lotan-Bilgelik"
  },
  Item_72842_StoryDesc = {
    Text = "Traphase - Sezon 14"
