  },
  Item_73466_Desc = {
    Text = "“Öte dünyadan gelen dostluğa ve Kozmik Han’daki Herkes’e, alkış!”"
  },
  Item_73466_EmojiName = {Text = "Alkış"},
  Item_73466_Name = {Text = "Alkış"},
  Item_73466_StoryDesc = {
    Text = "Sıram ile Ortak Etkinlik"
  },
  Item_73467_Desc = {
    Text = "“Boyut dalga denklemi mi? Gümüş çıkarma prensibi mi? O da ne? Üzgünüm… anlaşılan Işıyan Tanrıça bana bunu öğretmedi.”"
  },
  Item_73467_EmojiName = {Text = "Kuşku"},
  Item_73467_Name = {Text = "Bonnie"},
  Item_73467_StoryDesc = {
    Text = "Sıram ile Ortak Etkinlik"
  },
  Item_73468_Desc = {
    Text = "“Her ne kadar Traphase Bağlantı bazen… dengesiz olabilse de, bunun muhteşem bir maç olduğuna şüphe yok! Maçtan sonra beni arkadaş olarak ekleyip bir beğeni bırakmaya ne dersin?”"
  },
  Item_73468_EmojiName = {
