  Item_80189_Name = {
    Text = "Değer paketi boş"
  },
  Item_80191_Desc = {
    Text = "Bu Müfrezeyi kaydettikten sonra, Takım Dizilişi sırasında Müfreze becerisi: \"Kutsal İyileştirme\"yi seçebilirsin.\n\nSayısız Hastayı iyileştirdi, onları Topraktan Yeniden Doğuş'a kılavuzluk etti ve artık her şey yalnızca bir psikolojik tedaviden ibaret.\nTek fark, bu kez Hastanın kendisi olması."
  },
  Item_80191_Name = {
    Text = "Kutsal İyileştirme"
  },
  Item_80191_StoryDesc = {
    Text = "Sayısız Hasta’yı iyileştirdi, onları Topraktan Yeniden Doğuş’a yönlendirdi ve şimdi olan her şey sadece bir psikolojik terapi.\nTek fark, Hastanın bizzat kendisi olması."
  },
  Item_80192_Desc = {
    Text = "Ruhsal sanatoryumda sürüklenen duygusal parçacıklar—onlara dokunulduğunda, çöküşün eşiğindeki birinin hafif mırıltısı işitilir.\nKoruyucu’nun Rezonans’ını \"Başkalaşım\" Soruşturma Etkinliği’nde güçlendirmek için kullanılır."
  },
  Item_80192_Name = {
    Text = "Biliş Kalbi"
  },
  Item_80285_Desc = {
    Text = "Tüm Görevlerin Kilidini Aç ve Hepsini Tamamla, Ekstra Ödülleri Al"
  },
  Item_80285_Name = {
    Text = "Sanatoryum Arşivleri"
  },
  Item_81021_Desc = {
    Text = "Karen’in özel yapım temizlik aletleri; hiçbir şeyi geride bırakmadan, zahmetsiz bir pürüzsüzlükle silip süpürebilir."
  },
  Item_81021_Name = {
    Text = "Temizlik Puanları"
  },
  Item_81069_Desc = {
    Text = "Lojistik Departmanı, “Soruşturma”yı tamamlayan Koruyucu’lara özel izinler vermiştir. Her soruşturmanın ardından Koruyucu’lar, bir sonraki seferleri için özel işlenmiş, kıymetli Gümüş satın alabilir.\nStoklar sınırlıdır. Gümüş Anahtar Bize Yol Göstersin."
  },
  Item_81069_Name = {
    Text = "Kilometre Taşı: Yıldız Bölümü II"
  },
  Item_81250_Desc = {
    Text = "Bu işaret sancağı, 'Gemide Seyrüseferci var' anlamına gelir. Corposant bunları topluyor. Etkinlik dükkânında bunları çeşitli eşyalarla takas edebilirsin."
  },
  Item_81250_Name = {
    Text = "Sinyal Sancağı"
  },
  Item_81701_Desc = {
    Text = "Bu sinyal bayrağı 'Gemide navigatör var' anlamına gelir. Corposant bunları topluyor. Etkinlik mağazasında çeşitli eşyalarla değiştirebilirsiniz.\n\nEn az {s1} düşer"
  },
  Item_81701_Name = {
    Text = "Sinyal Sancağı"
