  Item_9674_Name = {Text = "Pandia"},
  Item_9675_Desc = {
    Text = "Milyonlarca yıl önce sıcak okyanuslarda baskındılar.\nUzun saplı bir deniz zambağının fosili.\nAequor Uyandırıcılarının yeteneklerini güçlendirmek için kullanılan bir malzeme."
