  Item_97139_Desc = {
    Text = "Pickman Stüdyosu’na özel, temel resim malzemeleri ve pratik araçlar içeren, sanat salonuna kolayca adım atmana yardımcı olacak bir başlangıç seti.\n\"Tuvalin Karanlık Yüzü\" etkinliği süresince sınırlı sayıda."
  },
  Item_97139_Name = {
