  Item_9854_Name = {
    Text = "Kızıl Kucaklayış V"
  },
  Item_9854_StoryDesc = {
    Text = "Efsaneler, ilk golemin yaratıcısının onu kendi elleriyle yok ettiğini söyler."
  },
  Item_9855_Desc = {
    Text = "Hasar Güçlendirmesi özelliğine sahip Kader Çarkı."
