  Item_9995_Desc = {
    Text = "Bu Müfrezeyi kaydettikten sonra, dizilim sırasında Müfreze becerisi \"Funus Aeternum\"u seçebilirsin.\n\nOna pek yardım edemedim; sahte tanrının inişini tek başına durdurdu.\nRuhu yok olmayacak; özgürlüğün bir yıldızı olarak sonsuza dek parlayacak."
  },
  Item_9995_Name = {
